CREATE TRIGGER "EventType_instantMeetingParameters_INSERT_array"
BEFORE INSERT ON "EventType" WHEN NEW."instantMeetingParameters" IS NOT NULL
BEGIN
    SELECT CASE WHEN NOT json_valid(NEW."instantMeetingParameters") THEN RAISE(ABORT, 'invalid list JSON')
        WHEN json_type(NEW."instantMeetingParameters") <> 'array' THEN RAISE(ABORT, 'expected list array') END;
    SELECT CASE WHEN EXISTS (SELECT 1 FROM json_each(NEW."instantMeetingParameters") WHERE type <> 'text')
        THEN RAISE(ABORT, 'invalid list element') END;
END;

CREATE TRIGGER "EventType_instantMeetingParameters_UPDATE_array"
