CREATE TRIGGER "Availability_days_INSERT_array"
BEFORE INSERT ON "Availability" WHEN NEW."days" IS NOT NULL
BEGIN
    SELECT CASE WHEN NOT json_valid(NEW."days") THEN RAISE(ABORT, 'invalid list JSON')
        WHEN json_type(NEW."days") <> 'array' THEN RAISE(ABORT, 'expected list array') END;
    SELECT CASE WHEN EXISTS (SELECT 1 FROM json_each(NEW."days") WHERE type <> 'integer' OR value NOT BETWEEN -2147483648 AND 2147483647)
        THEN RAISE(ABORT, 'invalid list element') END;
END;

